// ============================================================================
// CORRECTED: Filter Opted-In Customers Node Code
// ============================================================================
// Purpose: Filter customers who have NOT opted out + apply target audience
// Issue Fixed: Original code was not filtering - just passing through all data
// ============================================================================

// ✅ CORRECT: Get campaign that actually passed the Draft status check
const campaign = $node["Check Campaign Status = Draft"].json;

// Get all customers from input
const customers = $input.all();

console.log(`Total customers from sheet: ${customers.length}`);

// STEP 1: Filter customers who have NOT opted out
// Opt_Out_Promotional can be: false, "FALSE", "", null, undefined
let optedInCustomers = customers.filter(customer => {
  const optOutValue = customer.json["Opt_Out_Promotional"];

  // Consider opted-in if:
  // - false (boolean)
  // - "FALSE" (string)
  // - "" (empty string)
  // - null
  // - undefined
  const isOptedIn = (
    optOutValue === false || 
    optOutValue === "FALSE" || 
    optOutValue === "" || 
    optOutValue === null || 
    optOutValue === undefined
  );

  return isOptedIn;
});

console.log(`Customers opted-in (Opt_Out_Promotional = false): ${optedInCustomers.length}`);

// STEP 2: Apply target audience filter from campaign
const targetAudience = campaign["Target_Audience"];
console.log(`Target Audience: ${targetAudience}`);

let filteredCustomers = optedInCustomers;

if (targetAudience === "VIP") {
  // Filter where Customer Tier = "VIP"
  filteredCustomers = optedInCustomers.filter(c => 
    c.json["Customer Tier"] === "VIP"
  );
  console.log(`Filtered to VIP customers: ${filteredCustomers.length}`);

} else if (targetAudience === "Recent Buyers") {
  // Filter customers who ordered in last 30 days
  // Last Order Date is Excel date serial number
  const thirtyDaysAgo = Date.now() - (30 * 24 * 60 * 60 * 1000);
  const excelThirtyDaysAgo = (thirtyDaysAgo / 86400000) + 25569; // Convert to Excel date

  filteredCustomers = optedInCustomers.filter(c => {
    const lastOrderDate = parseFloat(c.json["Last Order Date"]);
    return !isNaN(lastOrderDate) && lastOrderDate > 0 && lastOrderDate >= excelThirtyDaysAgo;
  });
  console.log(`Filtered to Recent Buyers (last 30 days): ${filteredCustomers.length}`);

} else {
  // "All" or any other value - use all opted-in customers
  console.log(`Using all opted-in customers: ${filteredCustomers.length}`);
}

// STEP 3: Return filtered customers with necessary fields for next nodes
return filteredCustomers.map(customer => ({
  json: {
    campaign_id: campaign["Campaign_ID"],
    campaign_name: campaign["Campaign_Name"],
    customer_phone: customer.json["Customer Phone"], 
    customer_name: customer.json["Customer Name"] || "Valued Customer",
    customer_city: customer.json["Customer City"] || "",
    customer_tier: customer.json["Customer Tier"] || "Regular",
    message_template: campaign["Message_Text"],
    image_filename: campaign["Image_Filename"],
    target_audience: campaign["Target_Audience"]
  }
}));

// ═══════════════════════════════════════════════════════════════════════════
// Prepare WhatsApp Template Message - WITH CLOUDINARY IMAGE SUPPORT
// ═══════════════════════════════════════════════════════════════════════════

const customer = $input.first().json;
const campaign = $node["Check Campaign Status = Draft"].json;

// ═══════════════════════════════════════════════════════════════════════════
// STEP 1: Get template information from campaign
// ═══════════════════════════════════════════════════════════════════════════

const templateName = campaign.WhatsApp_Template_Name;
const phoneNumberId = '934770033042697';

console.log(`📤 [Prepare Template] Template: ${templateName} for ${customer.customer_phone}`);

// ═══════════════════════════════════════════════════════════════════════════
// STEP 2: Build template parameters array (Body parameters)
// ═══════════════════════════════════════════════════════════════════════════

const templateParams = [];

// Extract all Template_Var_X columns
for (let i = 1; i <= 10; i++) {
  const varKey = `Template_Var_${i}`;
  const varValue = campaign[varKey];

  if (varValue === null || varValue === undefined || varValue === "") {
    continue;
  }

  let value = String(varValue);

  // Replace placeholders
  value = value.replace(/\{\{customer_name\}\}/g, customer.customer_name || 'Valued Customer');
  value = value.replace(/\{\{customer_city\}\}/g, customer.customer_city || '');

  templateParams.push({
    type: "text",
    text: value
  });

  console.log(`📋 [Prepare Template] Param ${i}: ${value}`);
}

console.log(`📋 [Prepare Template] Body parameters: ${templateParams.length}`);

// ═══════════════════════════════════════════════════════════════════════════
// STEP 3: Build components array (Header + Body)
// ═══════════════════════════════════════════════════════════════════════════

const components = [];

// Check if campaign has image URL (from Cloudinary or any HTTPS source)
const imageUrl = campaign.Image_URL; // Column S in Google Sheets

if (imageUrl && imageUrl !== "" && imageUrl.startsWith("https://")) {
  // Add header component with image
  components.push({
    type: "header",
    parameters: [
      {
        type: "image",
        image: {
          link: imageUrl  // Direct Cloudinary URL
        }
      }
    ]
  });

  console.log(`📸 [Prepare Template] Header image URL: ${imageUrl}`);
} else {
  console.log(`⚠️ [Prepare Template] No valid image URL found. Skipping header.`);
}

// Add body component
components.push({
  type: "body",
  parameters: templateParams
});

// ═══════════════════════════════════════════════════════════════════════════
// STEP 4: Build WhatsApp Official API payload
// ═══════════════════════════════════════════════════════════════════════════

const whatsappUrl = `https://graph.facebook.com/v24.0/${phoneNumberId}/messages`;
const cleanPhone = String(customer.customer_phone).replace('@c.us', '');

const whatsappBody = {
  messaging_product: "whatsapp",
  to: cleanPhone,
  type: "template",
  template: {
    name: templateName,
    language: {
      code: "en"
    },
    components: components
  }
};

// ═══════════════════════════════════════════════════════════════════════════
// STEP 5: Return prepared data
// ═══════════════════════════════════════════════════════════════════════════

console.log(`✅ [Prepare Template] Message ready for ${cleanPhone}`);
console.log(`📦 [Prepare Template] Components: ${components.length} (Header: ${imageUrl ? 'Yes' : 'No'}, Body: Yes)`);

return {
  campaign_id: customer.campaign_id,
  customer_phone: cleanPhone,
  customer_name: customer.customer_name,
  template_name: templateName,
  whatsappUrl: whatsappUrl,
  whatsappBody: whatsappBody,
  sent_at: new Date().toISOString(),

  _metadata: {
    template_params_count: templateParams.length,
    phone_number_id: phoneNumberId,
    has_image: !!imageUrl,
    image_url: imageUrl || null,
    components_count: components.length
  }
};

